"""Original toxicology: toxic alcohols, lithium and cellular/hemoglobin poisons."""
from create_critical_antidotes import rows,q,AH,IC,AC,AP,NA,SA,ref
ME=ref('EXTRIP methanol recommendations','https://www.extrip-workgroup.org/methanol')
EG=ref('EXTRIP ethylene glycol recommendations','https://www.extrip-workgroup.org/ethylene-glycol')
LI=ref('EXTRIP lithium recommendations','https://www.extrip-workgroup.org/lithium')
CO=ref('CDC clinical guidance for carbon monoxide poisoning','https://www.cdc.gov/carbon-monoxide/hcp/clinical-guidance/index.html')

q('After ingesting illicit alcohol, a patient develops visual disturbance and high-anion-gap acidosis. Which toxic metabolite is chiefly responsible for the characteristic injury?', 'Formate from methanol metabolism',[
 ('Oxalate from ethylene glycol','This is associated with renal crystal injury rather than the classic methanol visual syndrome.'),('Acetone from isopropanol','This produces ketosis without the characteristic organic-acid gap pattern.'),('Acetaldehyde from ethanol','This does not explain the classic severe formate-mediated visual toxicity.')],
 'The metabolite can be more dangerous than the parent alcohol','**Alcohol dehydrogenase initiates methanol conversion to toxic downstream acids.**',['Formate impairs cellular energy metabolism and threatens vision.','Symptoms can be delayed while the parent compound is metabolized.'],'**Block further metabolism and assess urgently for dialysis.**',['Fomepizole is preferred when available; use a specialist protocol.','Treat acidosis and provide indicated folate-related adjunctive treatment.'],[['Methanol','Formate; visual/CNS injury'],['Ethylene glycol','Acid metabolites and oxalate'],['Isopropanol','Acetone; ketosis']],[ME],style='clinical_scenario')

q('Ethylene glycol poisoning is most strongly supported by which combination?', 'High-gap metabolic acidosis, AKI and calcium oxalate crystalluria in a compatible exposure',[
 ('Isolated ketosis without acidosis and acetone odor','This is more characteristic of isopropanol.'),('Visual blurring with formate accumulation','This favors methanol.'),('Respiratory alkalosis with tinnitus','This favors salicylate toxicity.')],
 'Ethylene glycol causes acid and renal injury','**Glycolate contributes to acidosis and oxalate can injure the kidney.**',['Hypocalcemia may occur but is not required.','Absence of urinary crystals does not exclude the poisoning.'],'**Start metabolism blockade when strongly suspected and obtain toxicology/nephrology input.**',['Do not wait for crystals or a send-out level in a deteriorating patient.','Dialysis decisions use severity, metabolite/gap burden and the antidote context.'],[['Acid burden','Glycolate'],['Kidney injury','Oxalate-related plus other mechanisms'],['Crystals','Supportive, not required']],[EG])

q('Why does a normal osmolar gap not exclude late methanol or ethylene glycol poisoning?', 'The parent alcohol may already have been converted into acidic metabolites',[
 ('The osmolar gap directly measures only formate concentration','It is a calculated difference, not a specific metabolite assay.'),('Organic acids always lower the anion gap to zero','Accumulation generally increases the anion gap.'),('A normal gap establishes that no toxic alcohol was absorbed','Timing and the broad normal range limit this inference.')],
 'Osmolar and anion gaps evolve with metabolism','**Early parent alcohol can raise the osmolar gap before major acidosis develops.**',['Later, acid metabolites can dominate while the osmolar gap falls.','Ethanol and other solutes complicate calculation and interpretation.'],'**Use exposure, serial chemistry and specific testing together.**',['Do not rule out treatment solely because one screening calculation is normal.','Consult early when visual, renal or severe acid-base toxicity suggests exposure.'],[['Early','Parent alcohol/osmolar effect'],['Later','Metabolite/anion-gap effect'],['Normal osmolar gap','Not an exclusion test']],[ME,EG])

q('What is the principal antidotal mechanism of fomepizole?', 'Inhibition of alcohol dehydrogenase',[
 ('Direct binding and removal of oxalate crystals','It prevents further metabolite formation but does not extract deposited crystals.'),('Activation of aldehyde dehydrogenase to accelerate acid production','That would not be the desired protective mechanism.'),('Neutralization of acid through bicarbonate delivery','Fomepizole is an enzyme inhibitor, not a buffer.')],
 'Prevent additional toxic-metabolite formation','**Blocking the first metabolic step limits conversion of methanol and ethylene glycol.**',['Existing toxic metabolites and severe organ injury may still require dialysis.','Antidote dosing must account for extracorporeal clearance when applicable.'],'**Treat before irreversible injury develops when the risk assessment warrants it.**',['Use drug levels and chemistry to guide duration under specialist advice.','Do not assume an antidote alone reverses established visual or kidney injury.'],[['Target','Alcohol dehydrogenase'],['Benefit','Less new toxic metabolite'],['Limit','Existing acid/organ injury remains']],[ME,EG])

q('A patient has isopropanol exposure, CNS depression, an osmolar gap and ketonemia, but no significant metabolic acidosis. Which statement is most appropriate?', 'Acetone formation explains ketosis without the typical high-gap acid burden',[
 ('The pattern proves methanol-related formate toxicity','Methanol more typically causes organic-acid accumulation and visual toxicity.'),('Fomepizole is routinely required to stop a uniquely toxic acid metabolite','Routine blockade is generally not indicated for uncomplicated isopropanol poisoning.'),('Ketonemia necessarily proves diabetic ketoacidosis','Ketoacidosis requires the appropriate acid-base and clinical context.')],
 'Ketosis and ketoacidosis are different findings','**Isopropanol is metabolized to acetone, a ketone rather than an organic acid.**',['Supportive respiratory/hemodynamic care is the foundation.','Severe refractory toxicity requires specialist escalation.'],'**Evaluate coingestants and other causes if significant acidosis is present.**',['Hypoperfusion can add lactate in severe cases.','Do not apply the methanol pathway indiscriminately to every alcohol exposure.'],[['Parent','Isopropanol'],['Metabolite','Acetone'],['Typical acid-base clue','Ketosis without substantial gap acidosis']],[IC],style='clinical_scenario')

q('A patient on chronic lithium develops AKI, coarse tremor, ataxia and confusion after dehydration. Which interpretation is most appropriate?', 'Clinically significant chronic lithium toxicity can occur at concentrations lower than those producing severe acute-ingestion toxicity',[
 ('A concentration below an acute-overdose cutoff excludes toxicity','Chronic tissue exposure and kidney function change level–effect relationships.'),('Activated charcoal reliably clears lithium from the gut','Lithium is poorly adsorbed.'),('Neurological symptoms are unrelated because lithium only affects the heart','Neurotoxicity is a major manifestation.')],
 'Interpret a lithium level in its exposure pattern','**Chronic accumulation distributes lithium into tissues before presentation.**',['Dehydration, reduced kidney clearance and interacting drugs can raise risk.','A single level does not capture the entire neurological burden.'],'**Stop lithium, correct appropriate volume deficits and assess dialysis need.**',['Review renal function, ECG and serial concentrations.','Use clinical severity and EXTRIP criteria rather than a number alone.'],[['Acute ingestion','Serum rise may precede tissue distribution'],['Chronic toxicity','Neurological burden at lower levels'],['Assessment','Pattern, symptoms and clearance']],[LI],style='clinical_scenario')

q('Why are serial lithium concentrations needed after hemodialysis?', 'Redistribution from tissues or continuing absorption can cause rebound',[
 ('Dialysis creates new lithium through a chemical reaction','It removes lithium; it does not synthesize it.'),('The first post-dialysis level always equals the final equilibrated tissue concentration','Compartment equilibration can take time.'),('Lithium becomes irreversibly bound to albumin during dialysis','It is minimally protein-bound and readily dialyzable.')],
 'The serum compartment can refill after extracorporeal removal','**Lithium is dialyzable, but body compartments do not equilibrate instantaneously.**',['Modified-release ingestions can add ongoing absorption.','The significance of rebound depends on magnitude, duration and symptoms.'],'**Monitor clinical state and serial levels after stopping treatment.**',['Repeat extracorporeal treatment may be needed.','Avoid restarting interacting medications until the precipitating factors are addressed.'],[['During HD','Serum level falls'],['After HD','Redistribution/absorption may raise it'],['Follow-up','Serial levels plus neurological assessment']],[LI])

q('A family exposed to an indoor generator has headache and confusion. A standard pulse oximeter reads 99%. Which test best evaluates the suspected exposure?', 'Blood carboxyhemoglobin measured by co-oximetry',[
 ('Standard pulse oximetry repeated on another finger as the exclusion test','Conventional devices cannot reliably distinguish carboxyhemoglobin from oxyhemoglobin.'),('PaO2 alone','Dissolved oxygen can be normal despite impaired oxygen carriage and cellular toxicity.'),('D-dimer as the specific confirmation','This is not a carbon monoxide assay.')],
 'A reassuring oxygen saturation can be misleading','**Carbon monoxide compromises oxygen delivery and has cellular effects beyond the measured saturation.**',['Provide high-concentration oxygen promptly.','A delayed sample after oxygen may underestimate the initial exposure.'],'**Assess neurological and cardiac injury and discuss hyperbaric treatment when indicated.**',['Pregnancy and severe manifestations alter risk assessment.','Exposure history and clinical severity matter more than an isolated late level.'],[['Standard SpO2','Can be falsely reassuring'],['PaO2','May remain normal'],['Confirmation','Co-oximetry COHb']],[CO],style='clinical_scenario')

q('A smoke-inhalation victim from an enclosed-space fire has cardiovascular collapse and severe lactic acidosis. Which empiric antidote is most appropriate when cyanide toxicity is strongly suspected?', 'Hydroxocobalamin',[
 ('Nitrite-induced methemoglobinemia as the preferred first choice despite possible concurrent CO exposure','Further reducing functional hemoglobin is undesirable in combined smoke-related hypoxia.'),('Naloxone as a cyanide-binding agent','Naloxone reverses opioid effects rather than binding cyanide.'),('Fomepizole to block cyanide metabolism','Its target is alcohol dehydrogenase, not cyanide toxicity.')],
 'Cyanide prevents effective cellular oxygen utilization','**Hydroxocobalamin binds cyanide without deliberately generating methemoglobin.**',['Diagnosis is often clinical because confirmatory tests are too slow for collapse.','Carbon monoxide and inhalational airway injury can coexist.'],'**Treat oxygenation, ventilation and shock concurrently.**',['Antidote treatment must not delay standard resuscitation.','Be aware of red discoloration and laboratory/dialysis-device interference after treatment.'],[['Setting','Enclosed-space fire'],['Mechanism','Cellular respiration inhibition'],['Antidote','Hydroxocobalamin']],[AH],style='clinical_scenario')

q('After dapsone exposure, a patient has cyanosis, a saturation near 85%, normal PaO2 and chocolate-colored blood. What best confirms the suspected disorder?', 'Co-oximetry measurement of methemoglobin',[
 ('An arterial PaO2 alone','PaO2 reflects dissolved oxygen and may remain normal.'),('A normal chest radiograph','This does not measure dysfunctional hemoglobin.'),('Serum bicarbonate as the specific test','Acidosis may reflect severity but is not diagnostic of the hemoglobin species.')],
 'Dyshemoglobinemia creates a saturation–oxygen-tension mismatch','**Ferric hemoglobin cannot carry oxygen normally and alters remaining-site affinity.**',['Co-oximetry identifies the abnormal hemoglobin fraction.','Treatment depends on symptoms, level and comorbidity rather than color alone.'],'**Remove the oxidant and obtain expert-guided antidotal treatment.**',['Methylene blue has G6PD-related hemolysis and serotonergic interaction concerns.','Dapsone can cause recurrent toxicity requiring prolonged observation.'],[['PaO2','Can be normal'],['Pulse SpO2','Often near mid-eighties'],['Diagnosis','Measured methemoglobin']],[AH],style='clinical_scenario')
